  (function(){
    // Search bar toggle
    var btn = document.getElementById('mag-search-btn');
    var bar = document.getElementById('mag-search-bar');
    if (btn && bar) {
      btn.addEventListener('click', function(){ bar.classList.toggle('d-none'); });
    }

    // Ticker: carrega posts recentes
    var ticker = document.getElementById('mag-ticker-items');
    if (ticker) {
      fetch('/feeds/posts/default?alt=json&max-results=8&orderby=published')
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(data){
          if (!data || !data.feed || !data.feed.entry) return;
          ticker.innerHTML = data.feed.entry.map(function(e){
            var lnk = (e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
            var url = lnk ? lnk.href : '#';
            var t = (e.title||{}).$t || '';
            return '<a class="text-white text-decoration-none" href="'+url+'">'+t+'</a>';
          }).join('<span class="mx-3 text-white-50" aria-hidden="true">·</span>');
        })
        .catch(function(){
          var bar2 = ticker.closest && ticker.closest('.mag-ticker-bar');
          if (bar2) bar2.style.display = 'none';
        });
    }
  })();
  //





  [[NICHO_JS]]
